CREATE DATABASE IF NOT EXISTS webboard CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE webboard;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(254) NOT NULL UNIQUE,email VARCHAR(254) NULL UNIQUE,full_name VARCHAR(120) NOT NULL DEFAULT '',password_hash VARCHAR(255) NOT NULL,profile_image CHAR(36) NULL,role ENUM('member','admin') NOT NULL DEFAULT 'member',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE threads(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(160) NOT NULL,body TEXT NOT NULL,image_name CHAR(36) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE answers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,thread_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(160) NOT NULL,body TEXT NOT NULL,image_name CHAR(36) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(thread_id) REFERENCES threads(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(thread_id,created_at)) ENGINE=InnoDB;
CREATE TABLE login_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ip_hash CHAR(64) NOT NULL,username_hash CHAR(64) NOT NULL,attempted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(ip_hash,attempted_at),INDEX(username_hash,attempted_at),INDEX idx_login_attempts_expiry (attempted_at)) ENGINE=InnoDB;
CREATE TABLE request_limits(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,scope VARCHAR(32) NOT NULL,key_hash CHAR(64) NOT NULL,occurred_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(scope,key_hash,occurred_at),INDEX(occurred_at)) ENGINE=InnoDB;
